#include "Sim/JamBossRules.h"

#include "Sim/JamDashRules.h"
#include "Sim/JamFightOps.h"
#include "Sim/JamKatanaRules.h"

namespace
{
void StartSlam(FJamFight& Fight, const FVector2D& Point, const FJamBalanceData& Balance)
{
	const int32 Telegraph = JamSim::Ticks(Balance.SlamTelegraph);
	FJamHazard Circle;
	Circle.Id = Fight.NextId++;
	Circle.Owner = EJamSide::Boss;
	Circle.Pos = Point;
	Circle.Radius = Balance.SlamRadius;
	Circle.Damage = Balance.SlamDamage;
	Circle.StartTick = Fight.Tick;
	Circle.HitTick = Fight.Tick + Telegraph;
	Fight.Hazards.Add(Circle);
	Fight.Boss.SlamReadyTick = Fight.Tick + JamSim::Ticks(Balance.SlamCooldown);
	Fight.Boss.BusyUntilTick = Circle.HitTick + JamSim::Ticks(Balance.BossRecovery);
}

void StartVolley(FJamFight& Fight, const FJamBalanceData& Balance)
{
	FJamShot Memo;
	Memo.Kind = EJamProjectile::Memo;
	Memo.Speed = Balance.MemoSpeed;
	Memo.Radius = Balance.MemoRadius;
	Memo.Damage = Balance.MemoDamage;
	Memo.Life = Balance.MemoLife;
	const FVector2D Aim = Fight.Fighters[EJamSide::Boss].Facing;
	for (const FVector2D& Dir : JamBossRules::VolleyDirections(Aim, FMath::RoundToInt32(Balance.MemoCount), Balance.MemoSpread))
	{
		JamFightOps::Shoot(Fight, EJamSide::Boss, Dir, Memo);
	}
	Fight.Boss.VolleyReadyTick = Fight.Tick + JamSim::Ticks(Balance.VolleyCooldown);
	Fight.Boss.BusyUntilTick = Fight.Tick + JamSim::Ticks(Balance.BossRecovery);
}

/**
 * The stolen dash: out of a katana strike that is about to land, or across the arena at a hero who keeps away.
 * Fills the intent and says true when he dashes on this step.
 */
bool WantsToDash(const FJamFight& Fight, double Distance, const FJamBalanceData& Balance, FJamIntent& Intent)
{
	const FJamFighter& Boss = Fight.Fighters[EJamSide::Boss];
	const FJamFighter& Hero = Fight.Fighters[EJamSide::Hero];
	if (!Fight.Ledger.Has(EJamSide::Boss, EJamMechanic::Dash) || !JamDashRules::CanStart(Boss.Dash, Fight.Tick))
	{
		return false;
	}
	const bool bStrikeComes = Hero.Katana.bHitPending &&
		JamKatanaRules::InArc(Hero.Pos, Hero.Facing, Boss.Pos, Boss.Radius, Balance.KatanaRange, Balance.KatanaHalfArc);
	const bool bHeroIsFar = Distance > Balance.DashDistance + Balance.SlamRange;
	if (!bStrikeComes && !bHeroIsFar)
	{
		return false;
	}
	for (const FJamEvent& Event : Fight.Events)
	{
		if (Event.Type == EJamEvent::StealResolved && Event.Side == EJamSide::Boss)
		{
			Run.Stolen.Add(static_cast<EJamMechanic>(FMath::RoundToInt32(Event.Amount)));
		}
	}
}

/** The enemy's warning circle the fighter stands in, if there is one. */
const FJamHazard* CircleOver(const FJamFight& Fight, EJamSide Side)
{
	const FVector2D Pos = Fight.Fighters[Side].Pos;
	for (const FJamHazard& Hazard : Fight.Hazards)
	{
		if (Hazard.Owner != Side && FVector2D::Distance(Hazard.Pos, Pos) < Hazard.Radius + CircleMargin)
		{
			return &Hazard;
		}
	}
	return nullptr;
}

/** Seconds until a projectile ends on its own: at the arena wall or when its life runs out. */
double SecondsToTheEnd(const FJamProjectile& Flying, int32 Tick, float ArenaRadius)
{
	const double Life = FMath::Max(Flying.DieTick - Tick, 0) * JamSim::StepDt;
	const double SpeedSquared = Flying.Vel.SizeSquared();
	const double Inside = FMath::Square(static_cast<double>(ArenaRadius)) - Flying.Pos.SizeSquared();
	if (SpeedSquared < UE_KINDA_SMALL_NUMBER || Inside <= 0.0)
	{
	// The hero parries with his strike (T-044), like a person: no key of its own.
	Intent.bPrimary = Intent.bPrimary || (bParryNow && Side == EJamSide::Hero);
	Intent.bParry = bParryNow && Side == EJamSide::Boss;
	Intent.bDash = ThreatCount > 0 && !bParryNow;
	// The slash flies along the aim, which is at the boss: only his distance decides.
	const bool bFull = Me.Ultimate.Meter >= 1.f && Fight.Ledger.Has(Side, EJamMechanic::Ultimate);
	Intent.bUltimate = bFull && FVector2D::Distance(Me.Pos, Target.Pos) <= Balance.UltimateRange + Target.Radius;
	if (const FJamHazard* Circle = CircleOver(Fight, Side))
	{
		// Out of the circle first, by the shortest way; from its very centre any way is as good, so away from the enemy.
		const FVector2D Away = Me.Pos - Circle->Pos;
		Intent.Move = Away.IsNearlyZero() ? -Intent.Aim.Dir : Away.GetSafeNormal();
		Intent.bDash = true;
	}
	else if (IsUnderTheBlade(Fight, Side, Balance))
	{
		// A slow blade is walked out of; the dash is for the one that is about to land.
		Intent.Move = -Intent.Aim.Dir;
		Intent.bDash = Target.Katana.HitTick - Fight.Tick <= JamSim::Ticks(DodgeSeconds);
	}
	else if (bHasKatana && Fight.Ledger.Has(Side, EJamMechanic::Dash) && Side == EJamSide::Hero && JamBossRules::IsBusy(Fight))
	{
		// The boss stands after his attack: this is when the katana pays. Only with the dash in hand: next to him it is
		// the one way through a volley.
		Intent.Move = Intent.Aim.Dir;
	}
	return Intent;
}

int32 JamBotRules::Choose(const FJamFight& Fight, EJamStealPolicy Policy)
{
	const FJamStealState& Steal = Fight.Steal;
	if (Fight.Phase != EJamPhase::Steal || Fight.Tick < Steal.OpenTick)
	{
		return -1;
	}
