	 * RetryLowHealthRestore of full instead. */
	UPROPERTY()
	float RetryLowHealthShare = 0.f;

	UPROPERTY()
	float RetryLowHealthRestore = 0.f;

	/** The heal the Publisher drops (T-049): the health it gives back, never past full. */
	UPROPERTY()
